import React, { useState } from 'react';
import { useHistory } from 'react-router-dom';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css'; // Import calendar styles
import './builderPortfolio.css';

const BuilderPortfolio = () => {
  const history = useHistory();
  const [showMenu, setShowMenu] = useState(false);
  const [activeSection, setActiveSection] = useState('currentWork');
  const [date, setDate] = useState(new Date());

  const toggleMenu = () => setShowMenu(!showMenu);

  const handleMenuClick = (section) => {
    setActiveSection(section);
    setShowMenu(false);
  };

  const renderTable = () => {
    if (activeSection === 'currentWork') {
      return (
        <section>
          <h2>Current Work</h2>
          <table>
            <thead>
              <tr>
                <th>PID</th>
                <th>Current Work Name</th>
                <th>Status</th>
                <th>Location</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td><a href="project1.html">001</a></td>
                <td>Project Alpha</td>
                <td>In Progress</td>
                <td>Location A</td>
              </tr>
              <tr>
                <td><a href="project2.html">002</a></td>
                <td>Project Beta</td>
                <td>Completed</td>
                <td>Location B</td>
              </tr>
            </tbody>
          </table>
        </section>
      );
    } else if (activeSection === 'previousWork') {
      return (
        <section>
          <h2>Previous Work</h2>
          <table>
            <thead>
              <tr>
                <th>PID</th>
                <th>Previous Work Name</th>
                <th>Status</th>
                <th>Location</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td><a href="previous1.html">A01</a></td>
                <td>Old Project X</td>
                <td>Completed</td>
                <td>Location X</td>
              </tr>
              <tr>
                <td><a href="previous2.html">A02</a></td>
                <td>Old Project Y</td>
                <td>Completed</td>
                <td>Location Y</td>
              </tr>
            </tbody>
          </table>
        </section>
      );
    } else if (activeSection === 'calendar') {
      return (
        <section>
          <h2>Project Calendar</h2>
          <Calendar
            onChange={setDate}
            value={date}
          />
          <p>Selected Date: {date.toDateString()}</p>
          {/* Display reminders and deadlines here */}
        </section>
      );
    }
  };

  return (
    <div>
      <header>
        <button id="back-button" onClick={() => history.goBack()}>Back</button>
        <h1>Builder Portfolio</h1>
        <div className="hamburger-menu" onClick={toggleMenu}>
          &#9776; {/* Hamburger icon */}
        </div>
      </header>
      {showMenu && (
        <nav className="menu">
          <ul>
            <li onClick={() => handleMenuClick('currentWork')}>Current Work</li>
            <li onClick={() => handleMenuClick('previousWork')}>Previous Work</li>
            <li onClick={() => handleMenuClick('calendar')}>Calendar</li>
            <li onClick={() => history.push('/signout')}>Sign Out</li>
          </ul>
        </nav>
      )}
      <main>
        {renderTable()}
      </main>
    </div>
  );
};

export default BuilderPortfolio;
